    faqNumber: '1000844',
    name: 'Sistema CREPE (Polícia) – Instalação',
    type: 'Requisição de serviço',
    service: 'Instalação/atualização da aplicação',
    subject: 'Solicita instalação do Sistema CREPE (Polícia)',
    category: 'APLICATIVOS INTERNOS',
