    id: 'faq-10001055',
    faqNumber: '10001055',
    name: 'Reset de senha de rede',
    type: 'Requisição de serviço',
    service: 'Solicitação de nova senha',
    subject: 'Solicita reset de senha de rede',
    category: 'APLICATIVOS INTERNOS',
