    id: 'faq-1000565',
    faqNumber: '1000565',
    name: 'Informações sobre Segundo Monitor',
    type: 'Requisição de serviço',
    service: 'Suporte e solução de dúvida técnica/operacional',
    subject: 'Informações sobre segundo Monitor',
    category: 'EQUIPAMENTOS',
