    id: 'faq-1000558',
    faqNumber: '1000558',
    name: 'Central de Serviços',
    type: 'Requisição de serviço',
    service: 'Suporte e solução de dúvida técnica/operacional',
    subject: 'Central de Serviços',
    category: 'MURAL DE AVISOS',
