    id: 'faq-10001087-localizacao-equipamentos',
    faqNumber: '10001087',
    name: 'Localização de equipamentos',
    type: 'Requisição de serviço',
    service: 'Suporte e solução de dúvida técnica/operacional',
    subject: 'Localização de equipamentos',
